 @AfterEach void cleanup(){if(admin!=null&&schema!=null)admin.execute("drop schema "+schema+" cascade");}
 Map<String,Object> input(long qty,String request){var d=new LinkedHashMap<String,Object>();d.putAll(Map.of("sourceType","partner","specId",15L,"supplierCode","SUP-A","qty",qty,"date",java.time.LocalDate.now().toString(),"location","中国工程柜","ownerName","QA工程","requestId",request));return d;}
 Map<String,Object> receive(long qty,String request){return tx.execute(t->samples.create(input(qty,request)));}
 long count(String kind){return jdbc.queryForObject("select count(*) from plm_partner_record where kind=?",Long.class,kind);}
 List<Map<String,Object>> receiveTypes(int count){return tx.execute(t->{var rows=new ArrayList<Map<String,Object>>();for(int i=0;i<count;i++){var input=input(2,"bulk-fixture-"+i);input.put("sampleVersion","TYPE-"+i);rows.add(samples.create(input));}return rows;});}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(ints={101,183,201,500})
 void bulkReadReturnsEveryFilteredIdentityWithoutWritesOrTruncation(int count){
  var batches=receiveTypes(count);var ids=batches.stream().map(b->number(b.get("sampleIdentityId"))).toList();long events=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);
  long started=System.nanoTime();var result=registry.query(Map.of("filters",Map.of("supplierCode","SUP-A")));var rows=maps(result.get("content"));assertThat(rows).hasSize(count);assertThat(rows.stream().map(r->number(r.get("sampleIdentityId")))).containsExactlyInAnyOrderElementsOf(ids);
  var selected=registry.query(Map.of("ids",ids,"details",true));assertThat(maps(selected.get("content"))).hasSize(count).allSatisfy(row->assertThat(maps(row.get("batches"))).singleElement().satisfies(batch->{assertThat(batch).containsEntry("canCorrectReceipt",true);assertThat(maps(map(batch.get("balances")).get("positions"))).singleElement().satisfies(position->assertThat(number(position.get("available"))).isEqualTo(2L));}));
  var key=text(rows.get(0).get("groupKey"));var grouped=maps(registry.query(Map.of("groupKeys",List.of(key,key))).get("content"));assertThat(grouped).isNotEmpty().allSatisfy(row->assertThat(row).containsEntry("groupKey",key));
  assertThat(maps(registry.query(Map.of("ids",List.of())).get("content"))).isEmpty();assertThat(registry.query(Map.of("filters",Map.of("keyword","no-such-type")))).containsEntry("totalElements",0);
  assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(events);assertThat(count("sample_identity")).isEqualTo(count);System.out.println("BULK_READ_EVIDENCE count="+count+" elapsedMs="+(System.nanoTime()-started)/1_000_000+" complete=true readOnly=true");
 }
 @Test void bulkReadEnforcesObjectAndMexicoScopeAndValidatesOnlyItsEntry(){
  var batches=receiveTypes(2);long first=number(batches.get(0).get("sampleIdentityId")),second=number(batches.get(1).get("sampleIdentityId"));restricted=true;allowed.add(first);allowed.add(number(batches.get(0).get("id")));
  var visible=maps(registry.query(Map.of()).get("content"));assertThat(visible).hasSize(2);assertThat(visible.stream().filter(row->number(row.get("sampleIdentityId"))==second)).singleElement().satisfies(row->assertThat(maps(row.get("batches"))).isEmpty());assertThatThrownBy(()->registry.query(Map.of("ids",List.of(first,999999L)))).hasMessageContaining("未获授权");
  for(var invalid:List.of(Map.<String,Object>of("filters","bad"),Map.<String,Object>of("filters",Map.of("secret","bad")),Map.<String,Object>of("ids",List.of(-1)),Map.<String,Object>of("ids",List.of(first),"groupKeys",List.of("x"))))assertThatThrownBy(()->registry.query(invalid)).isInstanceOf(RuntimeException.class);
  restricted=false;role="mexico";user=2;assertThat(maps(registry.query(Map.of("details",true)).get("content"))).isEmpty();assertThatThrownBy(()->registry.query(Map.of("filters",Map.of("site","CN")))).hasMessageContaining("仅限墨西哥");
 }
 @Test void moreThan100LoansReturnsAndLocationChangesUseOneAtomicReplayableSubmission(){
  var batches=receiveTypes(101);var items=batches.stream().map(b->bulkItem(b,1)).toList();var command=new LinkedHashMap<String,Object>(Map.of("requestId","large-loan","date",java.time.LocalDate.now().toString(),"person","QA","due",java.time.LocalDate.now().plusDays(1).toString(),"items",items));
  long before=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);items.get(100).put("qty",3);assertThatThrownBy(()->tx.execute(t->actions.bulk("loan",command))).hasMessageContaining("数量不足");assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(before);items.get(100).put("qty",1);
  tx.execute(t->actions.bulk("loan",command));long saved=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);tx.execute(t->actions.bulk("loan",command));assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(saved);
  var rows=maps(registry.query(Map.of("details",true)).get("content"));assertThat(rows).hasSize(101).allSatisfy(row->assertThat(map(row.get("balances"))).containsEntry("borrowed",1L));
  var returns=rows.stream().map(row->{var loan=maps(row.get("loans")).get(0);return Map.<String,Object>of("sampleIdentityId",row.get("sampleIdentityId"),"version",row.get("version"),"allocations",List.of(Map.of("batchId",loan.get("batchId"),"loanId",loan.get("id"),"qty",1,"damaged",0,"location","中国工程柜")));}).toList();tx.execute(t->actions.bulk("return",Map.of("requestId","large-return","date",java.time.LocalDate.now().toString(),"items",returns)));
  var locations=new SampleLocationService(store);var target=tx.execute(t->locations.create(Map.of("site","CN","name","QA批量柜","requestId","large-location")));var moves=maps(registry.query(Map.of()).get("content")).stream().map(row->Map.<String,Object>of("sampleIdentityId",row.get("sampleIdentityId"),"version",row.get("version"))).toList();var moved=tx.execute(t->actions.bulk("move",Map.of("site","CN","mode","all_onhand","targetLocationId",target.get("id"),"requestId","large-move","items",moves)));assertThat(map(moved.get("totals"))).containsEntry("movedQty",202L);
  assertThat(maps(registry.query(Map.of()).get("content"))).hasSize(101).allSatisfy(row->assertThat(map(row.get("balances"))).containsEntry("onhand",2L).containsEntry("borrowed",0L));
 }
 @Test void moreThan100ReceiptDeletionsAndParcelRowsKeepTheirExistingRules(){
  var batches=receiveTypes(101);var rows=maps(registry.query(Map.of("details",true)).get("content"));var parcels=new SampleShipmentService(store,registry,mock(SupplierProfileService.class));var parcel=tx.execute(t->parcels.create(Map.of("requestId","large-parcel","direction","mexico_outbound","destination","MX","rows",rows.stream().map(row->Map.of("sampleIdentityId",row.get("sampleIdentityId"),"qty",1)).toList())));assertThat(maps(parcel.get("rows"))).hasSize(101);assertThat(parcel).containsEntry("status","draft");
  var items=rows.stream().map(row->{var batch=maps(row.get("batches")).get(0);return new LinkedHashMap<String,Object>(Map.of("sampleIdentityId",row.get("sampleIdentityId"),"version",row.get("version"),"allocations",List.of(new LinkedHashMap<>(Map.of("batchId",batch.get("id"),"batchVersion",batch.get("version"))))));}).toList();
  var last=maps(items.get(100).get("allocations")).get(0);last.put("batchVersion",999L);var command=Map.<String,Object>of("requestId","large-delete","reason","QA错误登记","items",items);long events=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);assertThatThrownBy(()->tx.execute(t->actions.bulk("void_receipt",command))).hasMessageContaining("记录已变化");assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(events);last.put("batchVersion",maps(rows.get(100).get("batches")).get(0).get("version"));
  tx.execute(t->actions.bulk("void_receipt",command));long saved=jdbc.queryForObject("select count(*) from plm_partner_event",Long.class);tx.execute(t->actions.bulk("void_receipt",command));assertThat(jdbc.queryForObject("select count(*) from plm_partner_event",Long.class)).isEqualTo(saved);assertThat(maps(registry.query(Map.of()).get("content"))).isEmpty();assertThat(maps(registry.query(Map.of("filters",Map.of("receiptStatus","voided"))).get("content"))).hasSize(101);assertThat(count("sample")).isEqualTo(batches.size()+1);
 }
 @Test void existingSampleGetsSupplierCodeInListsAndDetailsWithoutChangingItsRecordsEventsOrStock(){
  jdbc.update("update plm_supplier_profile set short_code='' where supplier_code='SUP-A'");
  var receipt=receive(4,"old-plain-sy");long id=number(receipt.get("sampleIdentityId"));String original=text(receipt.get("sampleCode"));
  jdbc.update("update plm_supplier_profile set short_code='XD' where supplier_code='SUP-A'");
  String records=jdbc.queryForObject("select jsonb_agg(to_jsonb(r)order by record_id)::text from plm_partner_record r",String.class),events=jdbc.queryForObject("select jsonb_agg(to_jsonb(e)order by event_id)::text from plm_partner_event e",String.class);
  var head=registry.detail(id);String readable=text(head.get("sampleCode"));assertThat(readable).startsWith("SY-XD-").endsWith(original.substring(3));assertThat(head).containsEntry("code",original).containsEntry("originalSampleCode",original);
  for(String keyword:List.of(original,readable)){var rows=maps(registry.page(Map.of("keyword",keyword)).get("content"));assertThat(rows).singleElement().satisfies(row->assertThat(row).containsEntry("sampleCode",readable).containsEntry("originalSampleCode",original));}
  assertThat(samples.detail(number(receipt.get("id")))).containsEntry("sampleCode",readable);assertThat(map(head.get("balances"))).containsEntry("onhand",4L);
  assertThat(jdbc.queryForObject("select jsonb_agg(to_jsonb(r)order by record_id)::text from plm_partner_record r",String.class)).isEqualTo(records);assertThat(jdbc.queryForObject("select jsonb_agg(to_jsonb(e)order by event_id)::text from plm_partner_event e",String.class)).isEqualTo(events);
 }
 @Test void newOldAndReservedSupplierLabelsResolveTheSameIdentityButWrongSupplierDoesNot(){
  var receipt=receive(2,"readable-scan");long id=number(receipt.get("sampleIdentityId"));String original=text(registry.detail(id).get("code")),label=text(receipt.get("sampleCode"));
  assertThat(registry.resolve(original)).containsEntry("sampleIdentityId",id).containsEntry("sampleCode",label);assertThat(registry.resolve(label)).containsEntry("sampleIdentityId",id);assertThat(registry.resolve(text(receipt.get("code")))).containsEntry("type","legacy_batch").containsEntry("sampleIdentityId",id);
  jdbc.update("insert into plm_supplier_short_code_reservation values('A','SUP-A')");jdbc.update("update plm_supplier_profile set short_code='A2' where supplier_code='SUP-A'");
  String current=text(registry.detail(id).get("sampleCode"));assertThat(current).startsWith("SY-A2-");assertThat(registry.resolve(label)).containsEntry("sampleIdentityId",id).containsEntry("sampleCode",current);assertThat(registry.resolve(current.toLowerCase(Locale.ROOT))).containsEntry("sampleIdentityId",id);
  assertThatThrownBy(()->registry.resolve("SY-OTHER-"+original.substring(3))).hasMessageContaining("不存在或未获授权");assertThatThrownBy(()->registry.resolve("SY-A2-../" )).hasMessageContaining("格式无效");
 }
